void refill(tb_t *tb) {
  uint32_t t = atomic_read(&tb->tokens) + tb->rate;
  if (t > tb->bucket) t = tb->bucket;
  atomic_write(&tb->tokens, t);
  wake_up(&tb->wq);
}
